ValidationRule.errorConditionFormula:
AND($RecordType.Name = "Agent",(OR(AND( TEXT(Number_of_Branches__c) =='0',OR( NOT(ISBLANK(Branch_Office_Country__c)) , NOT(ISBLANK(Branch_City__c))) ),
AND( TEXT(Number_of_Branches__c) !='0',OR( ISBLANK(Branch_Office_Country__c) , ISBLANK(Branch_City__c)) )
)))
